class Solution {
  public int findMaxPathScore(int[][] edges, boolean[] online, long k) {
    int n = online.length, m = edges.length;
    int[] head = new int[n], next = new int[m], indeg = new int[n];
    java.util.Arrays.fill(head, -1);
    for (int i = 0; i < m; i++) {
      next[i] = head[edges[i][0]];
      head[edges[i][0]] = i;
      indeg[edges[i][1]]++;
    }
    int[] order = new int[n];
    int qh = 0, qt = 0;
    for (int i = 0; i < n; i++) if (indeg[i] == 0) order[qt++] = i;
    while (qh < qt) {
      int u = order[qh++];
      for (int e = head[u]; e >= 0; e = next[e])
        if (--indeg[edges[e][1]] == 0) order[qt++] = edges[e][1];
    }
    int lo = 0, hi = 1_000_000_000, ans = -1;
    long INF = Long.MAX_VALUE / 4;
    long[] dist = new long[n];
    while (lo <= hi) {
      int mid = (int) (((long) lo + hi) >>> 1);
      java.util.Arrays.fill(dist, INF);
      dist[0] = 0;
      for (int idx = 0; idx < qt; idx++) {
        int u = order[idx];
        if (dist[u] >= INF || (u != 0 && u != n - 1 && !online[u])) continue;
        for (int e = head[u]; e >= 0; e = next[e]) {
          int v = edges[e][1];
          if (edges[e][2] < mid || (v != n - 1 && !online[v])) continue;
          long d = dist[u] + edges[e][2];
          if (d < dist[v]) dist[v] = d;
        }
      }
      if (dist[n - 1] <= k) {
        ans = mid;
        lo = mid + 1;
      } else hi = mid - 1;
    }
    return ans;
  }
}
